CREATE TABLE payments(id UUID PRIMARY KEY,order_id UUID UNIQUE NOT NULL,status VARCHAR(20) NOT NULL,amount NUMERIC(12,2) NOT NULL,idempotency_key VARCHAR(100) UNIQUE NOT NULL,created_at TIMESTAMPTZ NOT NULL);CREATE TABLE refunds(id UUID PRIMARY KEY,payment_id UUID NOT NULL REFERENCES payments(id),status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL);CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMPTZ NOT NULL DEFAULT now());
